SELECT (SELECT has_function_privilege('service_role', 'public.export_workspace_rows(uuid, text, jsonb, int)', 'EXECUTE')) AS service_can, (SELECT has_function_privilege('authenticated', 'public.export_workspace_rows(uuid, text, jsonb, int)', 'EXECUTE')) AS authenticated_can, (SELECT count(*) FROM pg_proc WHERE proname = 'export_workspace_rows') AS overloads, (SELECT file_size_limit FROM storage.buckets WHERE id = 'workspace-merges') AS bucket_limit, (SELECT allowed_mime_types FROM storage.buckets WHERE id = 'workspace-merges') AS bucket_mime;
